import java.util.*;

class MinStack {
    private Deque<int[]> stack = new ArrayDeque<>(); // {value, min at push time}

    public MinStack() {
    }

    public void push(int val) {
        int m = stack.isEmpty() ? val : Math.min(val, stack.peek()[1]);
        stack.push(new int[]{val, m});
    }

    public void pop() {
        stack.pop();
    }

    public int top() {
        return stack.peek()[0];
    }

    public int getMin() {
        return stack.peek()[1];
    }
}

