class MinStack {
  constructor() { this.s = []; }
  push(v) { const n = this.s.length; this.s.push([v, n ? Math.min(v, this.s[n - 1][1]) : v]); }
  pop() { this.s.pop(); }
  top() { return this.s[this.s.length - 1][0]; }
  getMin() { return this.s[this.s.length - 1][1]; }
}
